package thaumcraft.test;
import java.util.*;
import com.mojang.authlib.GameProfile;
import net.minecraft.core.*;
import net.minecraft.core.component.DataComponents;
import net.minecraft.nbt.*;
import net.minecraft.server.level.*;
import net.minecraft.world.*;
import net.minecraft.world.item.*;
import net.minecraft.world.level.GameType;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.storage.TagValueInput;
import net.minecraft.util.ProblemReporter;
import net.minecraftforge.eventbus.api.listener.SubscribeEvent;
import net.minecraftforge.event.server.ServerStartedEvent;
import net.minecraftforge.fml.common.Mod;
import thaumcraft.alchemy.*;
import thaumcraft.essentia.*;
import thaumcraft.mirrors.*;
@Mod.EventBusSubscriber(modid="thaumcraft")
public final class TransfuserProbe {
 public static final BlockPos P=new BlockPos(67008,160,8),SAVED=P.east(64);static final Set<BlockPos> placed=new HashSet<>();
 public static void check(boolean ok,String s){if(!ok)throw new AssertionError(s);}
 public static void set(ServerLevel l,BlockPos p,net.minecraft.world.level.block.state.BlockState s){l.getChunkAt(p);l.setBlockAndUpdate(p,s);placed.add(p);}
 public static AlchemyMachine jar(ServerLevel l,BlockPos p,String aspect,int n,String filter){if(l.getBlockEntity(p)!=null)l.removeBlock(p,false);set(l,p,AlchemyContent.JAR.get().defaultBlockState());var m=(AlchemyMachine)l.getBlockEntity(p);if(n>0)m.insertEssence(aspect,n,false);if(!filter.isEmpty()){var item=new ItemStack(AlchemyContent.JAR.get());item.set(EssentiaContent.FILTER.get(),filter);m.placeContents(item);}return m;}
 public static TubeEntity tube(ServerLevel l,BlockPos p,TubeBlock.Kind kind,Map<String,Integer> amounts,String filter){set(l,p,EssentiaContent.TUBES.get(kind==TubeBlock.Kind.NORMAL?"tube":"tube_"+kind.name().toLowerCase(Locale.ROOT)).get().defaultBlockState());var t=(TubeEntity)l.getBlockEntity(p);var tag=t.saveWithoutMetadata(l.registryAccess());tag.put("essentia_network",TubeState.CODEC.encodeStart(NbtOps.INSTANCE,new TubeState(1,amounts,63,Collections.nCopies(6,0),filter,true,false,0)).getOrThrow());t.loadWithComponents(TagValueInput.create(ProblemReporter.DISCARDING,l.registryAccess(),tag));return t;}
 public static TransfuserEntity device(ServerLevel l,BlockPos p,Direction face,boolean fill){if(l.getBlockEntity(p)!=null)l.removeBlock(p,false);set(l,p,(fill?EssentiaContent.INPUT:EssentiaContent.OUTPUT).get().defaultBlockState().setValue(TransfuserBlock.FACING,face));return (TransfuserEntity)l.getBlockEntity(p);}
 public static TubeEntity receiver(ServerLevel l,BlockPos p,Direction facing,String aspect){var rear=p.relative(facing.getOpposite());var side=facing.getAxis()==Direction.Axis.X?Direction.NORTH:Direction.EAST;var t=tube(l,rear,TubeBlock.Kind.FILTER,Map.of(),aspect);var c=tube(l,rear.relative(side),TubeBlock.Kind.FILTER,Map.of(),aspect);jar(l,rear.relative(side).below(),"",0,aspect);for(int i=0;i<6;i++){c.serverTick();t.serverTick();}check(t.suction(facing)>0&&t.suctionType(facing).equals(aspect),"Native demand did not propagate");return t;}
 static void tick(TransfuserEntity t,int n){for(int i=0;i<n;i++)t.serverTick();}
 static void clear(ServerLevel l){for(var p:new ArrayList<>(placed))l.removeBlock(p,false);placed.clear();}
 static void brace(AlchemyMachine m){var l=m.getLevel();var tag=m.saveWithoutMetadata(l.registryAccess());tag.putBoolean("jar_braced",true);m.loadWithComponents(TagValueInput.create(ProblemReporter.DISCARDING,l.registryAccess(),tag));m.setChanged();}
 public static void load(TransfuserEntity t,TransfuserState state){var tag=t.saveWithoutMetadata(t.getLevel().registryAccess());tag.put("transfuser",TransfuserState.CODEC.encodeStart(NbtOps.INSTANCE,state).getOrThrow());t.loadWithComponents(TagValueInput.create(ProblemReporter.DISCARDING,t.getLevel().registryAccess(),tag));t.setChanged();}
 static void directions(ServerLevel l){for(var f:Direction.values()){clear(l);var t=device(l,P,f,true);var source=tube(l,P.relative(f.getOpposite()),TubeBlock.Kind.BUFFER,Map.of("aer",10),"");var dst=jar(l,P.relative(f,3),"",0,"");var back=jar(l,P.relative(f,-3),"ignis",5,"");for(var d:Direction.values()){check(t.connects(d)==(d==f.getOpposite()),"Wrong face connection");check(t.suction(d)==(d==f.getOpposite()?128:0),"Wrong suction face");check(!t.canOutput(d),"Filler exposes output");}tick(t,4);check(source.total()==10&&dst.total()==0,"Transfer before five ticks");tick(t,21);check(source.total()==5&&dst.total()==5&&back.total()==5&&t.snapshot().transferred()==5,"Filling direction/cadence/conservation "+f);
 clear(l);t=device(l,P,f,false);var receiver=receiver(l,P,f,"aer");source=null;var src=jar(l,P.relative(f,3),"aer",10,"");back=jar(l,P.relative(f,-3),"aer",10,"");tick(t,5);check(src.total()==9&&receiver.total()==1&&back.total()==10&&t.snapshot().transferred()==1,"Emptying direction "+f);tick(t,10);check(src.total()==9&&receiver.total()==1,"Full rear receiver drained more");check(receiver.extract("aer",f,false),"Receiver cannot be emptied");tick(t,5);check(src.total()==8&&receiver.total()==1&&t.snapshot().transferred()==2,"Typed delivery not resumed "+f);}clear(l);thaumcraft.Thaumcraft.LOGGER.info("TRANSFUSER71_DIRECTIONS_OK: six orientations, real filtered tube demand, cadence, back exclusion and conservation");}
 static void filters(ServerLevel l){var t=device(l,P,Direction.EAST,true);var source=tube(l,P.west(),TubeBlock.Kind.BUFFER,Map.of("aer",6,"ignis",4),"");var near=jar(l,P.east(2),"",0,"");var matching=jar(l,P.east(6),"aer",1,"");tick(t,5);check(near.total()==0&&matching.total()==2,"Did not prefer existing matching jar");brace(matching);tick(t,5);check(matching.total()==2&&near.total()==1,"Brace not respected");near=jar(l,P.east(2),"",0,"ignis");tick(t,5);check(near.aspects().getOrDefault("ignis",0)==1&&source.snapshot().aspects().get("aer")==4,"Jar filter ignored");l.removeBlock(P.east(2),false);int total=source.total();tick(t,10);check(source.total()==total&&t.snapshot().pending().isEmpty(),"Missing destination consumed input");var full=jar(l,P.east(2),"aer",250,"");tick(t,5);check(source.total()==total&&full.total()==250,"Full jar consumed input");set(l,P.east(2),AlchemyContent.VOID_JAR.get().defaultBlockState());var sink=(AlchemyMachine)l.getBlockEntity(P.east(2));sink.insertEssence("aer",250,false);tick(t,5);check(source.total()==total-1&&sink.total()==250,"Void jar overflow behavior changed");clear(l);thaumcraft.Thaumcraft.LOGGER.info("TRANSFUSER71_FILTERS_OK: filled priority, labels, braces, blocked/full destinations and void overflow");}
 static void mirrors(ServerLevel l){var t=device(l,P,Direction.EAST,true);var source=tube(l,P.west(),TubeBlock.Kind.BUFFER,Map.of("aer",3),"");var here=P.east(3);var there=P.east(40);set(l,here.west(),Blocks.STONE.defaultBlockState());set(l,there.west(),Blocks.STONE.defaultBlockState());set(l,here,MirrorContent.ESSENTIA.get().defaultBlockState().setValue(MirrorBlock.FACING,Direction.EAST));set(l,there,MirrorContent.ESSENTIA.get().defaultBlockState().setValue(MirrorBlock.FACING,Direction.EAST));var a=(MirrorEntity)l.getBlockEntity(here);var b=(MirrorEntity)l.getBlockEntity(there);check(a.bind(b.address()),"Mirror bind failed");var dst=jar(l,there.east(2),"",0,"");tick(t,5);check(source.total()==2&&dst.total()==1&&a.instability()>0,"Remote mirror delivery failed");brace(dst);tick(t,5);check(source.total()==2&&dst.total()==1,"Remote mirror bypassed brace");clear(l);thaumcraft.Thaumcraft.LOGGER.info("TRANSFUSER71_MIRRORS_OK: physical targets behind mirrors, flux cost and sealed remote jars");}
 static final class Receiver extends BlockEntity implements EssentiaTransport {boolean reject=true;int stored;Receiver(BlockPos p){super(AlchemyContent.TYPE.get(),p,AlchemyContent.JAR.get().defaultBlockState());}public boolean connects(Direction f){return true;}public boolean canInput(Direction f){return stored==0;}public boolean canOutput(Direction f){return false;}public Map<String,Integer> contents(Direction f){return Map.of();}public String suctionType(Direction f){return "aer";}public int suction(Direction f){return 64;}public int minimumSuction(){return 0;}public boolean insert(String a,Direction f,boolean sim){if(stored!=0||!a.equals("aer"))return false;if(!sim){if(reject)return false;stored++;}return true;}public boolean extract(String a,Direction f,boolean sim){return false;}}
 static void escrow(ServerLevel l){var t=device(l,P,Direction.EAST,false);set(l,P.west(),AlchemyContent.JAR.get().defaultBlockState());var receiver=new Receiver(P.west());l.setBlockEntity(receiver);var source=jar(l,P.east(3),"aer",10,"");tick(t,5);check(source.total()==9&&receiver.stored==0&&t.snapshot().pending().equals("aer"),"Receiver race lost/duplicated reserved essence");tick(t,10);check(source.total()==9&&t.snapshot().pending().equals("aer"),"Blocked reserve caused a second extraction");var drops=Block.getDrops(t.getBlockState(),l,P,t);check(drops.size()==1&&drops.getFirst().has(DataComponents.BLOCK_ENTITY_DATA),"Reserved block loot lost state");var raw=drops.getFirst().get(DataComponents.BLOCK_ENTITY_DATA);l.removeBlock(P,false);t=device(l,P,Direction.EAST,false);check(raw.loadInto(t,l.registryAccess())&&t.snapshot().pending().equals("aer"),"Reserved item re-placement lost unit");receiver.reject=false;tick(t,5);check(receiver.stored==1&&source.total()==9&&t.snapshot().pending().isEmpty()&&t.snapshot().transferred()==1,"Reserved delivery lost/duplicated essence");var tag=t.saveWithoutMetadata(l.registryAccess());tag.getCompoundOrEmpty("transfuser").putInt("version",2);t.loadWithComponents(TagValueInput.create(ProblemReporter.DISCARDING,l.registryAccess(),tag));check(!t.supported()&&!t.connects(Direction.WEST)&&t.suction(Direction.WEST)==0,"Future state remains active");var saved=Block.getDrops(t.getBlockState(),l,P,t).getFirst().get(DataComponents.BLOCK_ENTITY_DATA).copyTagWithoutId();check(saved.getCompoundOrEmpty("transfuser").getIntOr("version",0)==2,"Future state lost in loot");clear(l);thaumcraft.Thaumcraft.LOGGER.info("TRANSFUSER71_ESCROW_OK: adversarial receiver, no repeat extraction, native loot/re-placement and opaque future state");}
 static void saveScene(ServerLevel l){var t=device(l,SAVED,Direction.UP,false);jar(l,SAVED.below(),"aer",250,"aer");jar(l,SAVED.above(3),"aer",9,"");load(t,new TransfuserState(1,2,"aer",7));}
 static void read(ServerLevel l){l.getChunkAt(SAVED);var t=(TransfuserEntity)l.getBlockEntity(SAVED);check(t!=null&&t.snapshot().equals(new TransfuserState(1,2,"aer",7)),"Cold restart lost phase/reserved unit");var receiver=(AlchemyMachine)l.getBlockEntity(SAVED.below());var source=(AlchemyMachine)l.getBlockEntity(SAVED.above(3));check(receiver.total()==250&&source.total()==9,"Restart altered jars");receiver.extractEssence("aer",1,false);tick(t,3);check(receiver.total()==250&&source.total()==9&&t.snapshot().pending().isEmpty()&&t.snapshot().transferred()==8,"Restart duplicated extraction/payment");tick(t,10);check(source.total()==9,"Full jar drained after restart");thaumcraft.Thaumcraft.LOGGER.info("TRANSFUSER71_RESTART_OK: exact reserved unit and tick phase recovered in a second JVM");}
 @SubscribeEvent public static void start(ServerStartedEvent e){String mode=System.getProperty("thaumcraft.bookProbe","");if(!Set.of("transfuser-write","transfuser-read").contains(mode))return;var l=e.getServer().overworld();e.getServer().tickRateManager().setFrozen(false);for(int x=-2;x<=2;x++)for(int z=-2;z<=2;z++)l.getChunk((P.getX()>>4)+x,(P.getZ()>>4)+z);if(mode.endsWith("read"))read(l);else{for(int x=-2;x<=2;x++)for(int z=-2;z<=2;z++){var chunk=l.getChunk((P.getX()>>4)+x,(P.getZ()>>4)+z);for(var be:new ArrayList<>(chunk.getBlockEntities().values())){var pos=be.getBlockPos();if(Math.abs(pos.getX()-P.getX())<=48&&Math.abs(pos.getY()-P.getY())<=18&&Math.abs(pos.getZ()-P.getZ())<=18)l.removeBlock(pos,false);}}directions(l);filters(l);mirrors(l);escrow(l);saveScene(l);thaumcraft.Thaumcraft.LOGGER.info("TRANSFUSER71_WRITE_OK");}e.getServer().tickRateManager().setFrozen(true);e.getServer().halt(false);}
}
